package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var dateRec DateRec

var inputDone bool = false

var dateFileLines []string
var dateFileIdx int = 0

func formatNumeric(v int64, width int) string {
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	// truncation to low-order digits (for positive, modulo)
	// For negative handling not needed here, but handle
	if v < 0 {
		// keep sign? COBOL would handle separately; not needed
		v = ((v % mod) + mod) % mod
	} else {
		v = v % mod
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func formatP99(v int64) string {
	return formatNumeric(v, 2)
}
func formatP9n(v int64, n int) string {
	return formatNumeric(v, n)
}

func padRight(s string, length int) string {
	if len(s) >= length {
		if len(s) > length {
			return s[:length]
		}
		return s
	}
	return s + strings.Repeat(" ", length-len(s))
}

func parseIntField(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// keep only digits? COBOL expects digits
	// If contains spaces inside, trim
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// extract digits
		filtered := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				filtered += string(ch)
			}
		}
		if filtered == "" {
			return 0
		}
		n, _ = strconv.ParseInt(filtered, 10, 64)
		return n
	}
	return n
}

func loadDateFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		dateFileLines = []string{}
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Remove trailing \r if present (Scanner already strips \n, but may leave \r)
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		dateFileLines = append(dateFileLines, line)
	}
}

func READ_PARA() {
	if dateFileIdx >= len(dateFileLines) {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	raw := dateFileLines[dateFileIdx]
	dateFileIdx++
	// pad to 12 with spaces
	if len(raw) < 12 {
		raw = raw + strings.Repeat(" ", 12-len(raw))
	} else if len(raw) > 12 {
		raw = raw[:12]
	}
	dateRec.DtId = raw[0:4]
	dateRec.DtYyyy = parseIntField(raw[4:8])
	dateRec.DtMm = parseIntField(raw[8:10])
	dateRec.DtDd = parseIntField(raw[10:12])
}

func LEAP_PARA() {
	WsQ = dateRec.DtYyyy / 4
	WsR4 = dateRec.DtYyyy % 4
	WsQ = dateRec.DtYyyy / 100
	WsR100 = dateRec.DtYyyy % 100
	WsQ = dateRec.DtYyyy / 400
	WsR400 = dateRec.DtYyyy % 400
	// Apply PIC truncation for WsQ (9(4)) and remainders (9(3))
	WsQ = WsQ % 10000
	WsR4 = WsR4 % 1000
	WsR100 = WsR100 % 1000
	WsR400 = WsR400 % 1000
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch dateRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = WsMaxDay % 100
}

func PROCESS_PARA() {
	LEAP_PARA()
	if dateRec.DtMm < 1 || dateRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		fmt.Println(dateRec.DtId + " BAD MONTH " + formatNumeric(dateRec.DtMm, 2))
	} else {
		DAYS_PARA()
		if dateRec.DtDd < 1 || dateRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Println(dateRec.DtId + " BAD DAY " + formatNumeric(dateRec.DtDd, 2) + " MAX " + formatP99(WsMaxDay))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Println(dateRec.DtId + " VALID " + formatNumeric(dateRec.DtYyyy, 4) + "-" + formatNumeric(dateRec.DtMm, 2) + "-" + formatNumeric(dateRec.DtDd, 2))
		}
	}
	READ_PARA()
}

func MAIN_PARA() {
	loadDateFile()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Println("VALID: " + formatP99(WsValid) + " BAD MONTH: " + formatP99(WsBadMonth) + " BAD DAY: " + formatP99(WsBadDay))
}

func main() {
	MAIN_PARA()
}
